insert='''\n    def service_episode(t:int) -> None:\n        nonlocal execution_episode, supervisor_decision_done\n        if execution_episode is None:\n            return\n        combined_net=(actual.maker_up+actual.taker_up)-(actual.maker_down+actual.taker_down)\n        desired_net_now=(desired_maker["UP"]+desired_taker["UP"])-(desired_maker["DOWN"]+desired_taker["DOWN"])\n        track_signed=combined_net-desired_net_now; track_abs=abs(track_signed)\n        maker_signed=actual.maker_up-actual.maker_down; maker_abs=abs(maker_signed)\n        execution_episode["peakAbsError"]=max(float(execution_episode.get("peakAbsError",0.0)),track_abs)\n        execution_episode["peakMakerAbs"]=max(float(execution_episode.get("peakMakerAbs",0.0)),maker_abs)\n        if not bool(execution_episode.get("activeOwnership")):\n            bt0=float(execution_episode["baselineAbsError"]); bm0=float(execution_episode["baselineMakerAbs"])\n            if track_abs<=bt0+EPS and maker_abs<=bm0+EPS:\n                ep=dict(execution_episode); ep.update({"endMs":int(t),"durationMs":int(t)-int(ep["startMs"]),"recovered":True,"reason":"NATURAL_RECOVERY_BEFORE_CHECKPOINT"}); execution_episodes.append(ep); execution_episode=None; return\n            if int(t)-int(execution_episode["startMs"]) < 15000:\n                return\n            dtrack=max(0.0,track_abs-bt0); dmaker=max(0.0,maker_abs-bm0)\n            state={"atMs":int(t),"action":"SUPERVISOR_CF_DECISION","selected":EPISODE_OVERRIDE,"deltaTrack":dtrack,"deltaMaker":dmaker,"trackAbs":track_abs,"makerAbs":maker_abs,"trackSigned":track_signed,"makerSigned":maker_signed,"makerUp":float(actual.maker_up),"makerDown":float(actual.maker_down),"desiredMakerUp":float(desired_maker["UP"]),"desiredMakerDown":float(desired_maker["DOWN"]),"desiredTakerUp":float(desired_taker["UP"]),"desiredTakerDown":float(desired_taker["DOWN"]),"activeUp":active_maker.get("UP") is not None,"activeDown":active_maker.get("DOWN") is not None,"makerFillCount":sum(1 for e in fill_log if e.get("role")=="MAKER"),"toxCancelCount":sum(1 for e in toxicity_events if e.get("action")=="TOXIC_CANCEL_REQUEST"),"secondsLeft":float((latest_public_snapshot or {}).get("secondsLeft")) if (latest_public_snapshot or {}).get("secondsLeft") is not None else None}\n            episode_events.append(state)\n            supervisor_decision_done=True\n            if EPISODE_OVERRIDE=='NONE':\n                execution_episode=None; return\n            if EPISODE_OVERRIDE=='TRACKING':\n                signed=track_signed; baseline=bt0; kind='TRACKING'\n            elif EPISODE_OVERRIDE=='MAKER_NET':\n                signed=maker_signed; baseline=bm0; kind='MAKER_NET'\n            else:\n                raise RuntimeError(f'bad R2_EPISODE_OVERRIDE={EPISODE_OVERRIDE}')\n            if abs(signed)<=EPS:\n                execution_episode=None; return\n            recovery='DOWN' if signed>0 else 'UP'; worsening='UP' if signed>0 else 'DOWN'\n            execution_episode.update({"kind":kind,"activeOwnership":True,"activatedMs":int(t),"baselineOwnershipAbs":baseline,"recoverySide":recovery,"worseningSide":worsening})\n            num=active_maker.get(worsening); cancel_action='NO_ACTIVE_WORSENING_QUEUE'\n            if num is not None and worsening not in toxicity_pending:\n                cur=bt.orders(0).get(int(num))\n                if cur is not None and bool(cur.cancellable):\n                    try:\n                        bt.cancel(0,int(num),False); cancel_action='CANCEL_REQUESTED'\n                    except Exception:\n                        cancel_action='CANCEL_FAILED'\n            episode_events.append({"atMs":int(t),"action":"SUPERVISOR_ESCALATE_15S","kind":kind,"recoverySide":recovery,"worseningSide":worsening,"cancelAction":cancel_action})\n            return\n        metric=track_abs if execution_episode.get("kind")=="TRACKING" else maker_abs\n        if metric<=float(execution_episode["baselineOwnershipAbs"])+EPS:\n            ep=dict(execution_episode); ep.update({"endMs":int(t),"durationMs":int(t)-int(ep["startMs"]),"endAbs":metric,"recovered":True}); execution_episodes.append(ep); execution_episode=None\n\n'''
